localparam int unsigned NumDMADevices = 4;
localparam int unsigned DmaAxiIdWidth =
    ariane_soc::IdWidth - $clog2(NumDMADevices);

// AXI Bus between DMA devices and IOMMU TR IF
// Extended with AXI support for untranslated transactions
`AXI_TYPEDEF_EXT_ALL(axi_tr, iommu_addr_t, iommu_id_t, 
                        iommu_data_t, iommu_strb_t, iommu_user_t, 
                        rv_iommu::device_id_t, logic, rv_iommu::process_id_t)
axi_tr_req_t axi_iommu_tr_req;
axi_tr_resp_t axi_iommu_tr_resp;
`AXI_TYPEDEF_ALL(axi_comp, iommu_addr_t, iommu_id_t,
                        iommu_data_t, iommu_strb_t, iommu_user_t)
axi_comp_req_t  axi_iommu_comp_req;
axi_comp_resp_t axi_iommu_comp_resp;

typedef logic [DmaAxiIdWidth-1:0] dma_iommu_id_t;
`AXI_TYPEDEF_EXT_ALL(axi_dma_tr, iommu_addr_t, dma_iommu_id_t,
                        iommu_data_t, iommu_strb_t, iommu_user_t,
                        rv_iommu::device_id_t, logic, rv_iommu::process_id_t)
axi_dma_tr_req_t  [NumDMADevices-1:0] axi_dma_tr_req;
axi_dma_tr_resp_t [NumDMADevices-1:0] axi_dma_tr_resp;

for (genvar o = 0; o < NumDMADevices; o++) begin : gen_dma_observation
    assign obs_arvalid[o] = axi_dma_tr_req[o].ar_valid;
    assign obs_awvalid[o] = axi_dma_tr_req[o].aw_valid;
    assign obs_arready[o] = axi_dma_tr_resp[o].ar_ready;
    assign obs_awready[o] = axi_dma_tr_resp[o].aw_ready;
    assign obs_rlast[o] = axi_dma_tr_resp[o].r_valid && axi_dma_tr_resp[o].r.last && axi_dma_tr_req[o].r_ready;
    assign obs_b[o] = axi_dma_tr_resp[o].b_valid && axi_dma_tr_req[o].b_ready;
    // Each current iDMA emits AxID=0. Monitor its private mux-side ID.
    assign obs_bad_id[o] = (obs_arvalid[o] && |axi_dma_tr_req[o].ar.id) ||
        (obs_awvalid[o] && |axi_dma_tr_req[o].aw.id) ||
        (axi_dma_tr_resp[o].r_valid && |axi_dma_tr_resp[o].r.id) ||
        (axi_dma_tr_resp[o].b_valid && |axi_dma_tr_resp[o].b.id);

) i_dma_iommu_tr_mux (
    .clk_i,
    .rst_ni,
    .test_i      ( 1'b0              ),
    .slv_reqs_i  ( axi_dma_tr_req    ),
    .slv_resps_o ( axi_dma_tr_resp   ),
    .mst_req_o   ( axi_iommu_tr_req  ),
    .mst_resp_i  ( axi_iommu_tr_resp )
);

assign active = phase_q == HARDWARE || phase_q == POLL_WAIT || phase_q == REFILL;
assign v_pending = |reads_q[victim_q] || |writes_q[victim_q] ||
                   ar_valid_i[victim_q] || aw_valid_i[victim_q];
assign a_pending = has_a_q && (|reads_q[aggressor_q] || |writes_q[aggressor_q] ||
                              ar_valid_i[aggressor_q] || aw_valid_i[aggressor_q]);

// Track continuously, including warmup and drain, never reset on ARM.
for (int i = 0; i < NumPorts; i++) begin
    reads_n[i] = reads_q[i];
    writes_n[i] = writes_q[i];
    case ({ar_valid_i[i] && ar_ready_i[i], rlast_fire_i[i]})
        2'b10: begin
            reads_n[i] = reads_q[i] + 1'b1;
            if (&reads_q[i]) track_bad_n[i] = 1'b1;
        end
        2'b01: begin
            reads_n[i] = reads_q[i] - 1'b1;
            if (reads_q[i] == 0) track_bad_n[i] = 1'b1;
        end
        default: ; // Simultaneous acceptance/return has zero net change.
    endcase
    case ({aw_valid_i[i] && aw_ready_i[i], b_fire_i[i]})
        2'b10: begin
            writes_n[i] = writes_q[i] + 1'b1;
            if (&writes_q[i]) track_bad_n[i] = 1'b1;
        end
        2'b01: begin
            writes_n[i] = writes_q[i] - 1'b1;
            if (writes_q[i] == 0) track_bad_n[i] = 1'b1;
        end
        default: ;
    endcase

if (phase_q == ARMED && issue_i[victim_q]) begin
    phase_n = HARDWARE;
    expected_n = issue_id_i[victim_q];
    count_n[7] = 1;
    segment_n = 0;
    count_n[30] = CounterWidth'((CounterWidth'(reads_n[victim_q]) << 16) | CounterWidth'(writes_n[victim_q]));
    count_n[31] = has_a_q ? CounterWidth'((CounterWidth'(reads_n[aggressor_q]) << 16) | CounterWidth'(writes_n[aggressor_q])) : '0;
    if (issue_id_i[victim_q] == 0) error_n[1] = 1'b1;
end

if (phase_q == BATCH_READ) begin
    bump(34, 1'b1);
    if (issue_i[victim_q] || done_i[victim_q]) error_n[1] = 1'b1;
    if (poll_i[victim_q] && poll_id_i[victim_q] == expected_q) begin
        count_n[9] = 1;
        phase_n = FROZEN;
    end

if (active) begin
    bump(0, 1'b1);
    segment_n = segment_q + 1'b1;
    if (&segment_q) error_n[2] = 1'b1;
    bump(10 + int'({a_pending, v_pending}), 1'b1);
    for (int role = 0; role < 2; role++) begin
        if (role == 0 || has_a_q) begin
            bump(14 + role*6, ar_valid_i[role == 0 ? victim_q : aggressor_q] && ar_ready_i[role == 0 ? victim_q : aggressor_q]);
            bump(15 + role*6, aw_valid_i[role == 0 ? victim_q : aggressor_q] && aw_ready_i[role == 0 ? victim_q : aggressor_q]);
            bump(16 + role*6, rlast_fire_i[role == 0 ? victim_q : aggressor_q]);
            bump(17 + role*6, b_fire_i[role == 0 ? victim_q : aggressor_q]);
            bump(18 + role*6, ar_valid_i[role == 0 ? victim_q : aggressor_q] && !ar_ready_i[role == 0 ? victim_q : aggressor_q]);
            bump(19 + role*6, aw_valid_i[role == 0 ? victim_q : aggressor_q] && !aw_ready_i[role == 0 ? victim_q : aggressor_q]);
        end
    end
    bump(26, shared_ar_valid_i && shared_ar_ready_i);
    bump(27, shared_aw_valid_i && shared_aw_ready_i);
    bump(28, shared_ar_valid_i && !shared_ar_ready_i);
    bump(29, shared_aw_valid_i && !shared_aw_ready_i);

case (phase_q)
    HARDWARE: begin
        bump(1, 1'b1);
        if (issue_i[victim_q]) error_n[1] = 1'b1;
        if (done_i[victim_q]) begin
            if (done_id_i[victim_q] != expected_q) error_n[1] = 1'b1;
            bump(8, 1'b1);
            if (segment_n > count_q[4]) count_n[4] = segment_n;
            segment_n = 0;
            if (batch_q) begin
                if (64'(count_n[8]) == target_q) begin
                    phase_n = BATCH_READ;
                    count_n[32] = CounterWidth'((CounterWidth'(reads_n[victim_q]) << 16) | CounterWidth'(writes_n[victim_q]));
                    count_n[33] = has_a_q ? CounterWidth'((CounterWidth'(reads_n[aggressor_q]) << 16) | CounterWidth'(writes_n[aggressor_q])) : '0;
                end else phase_n = REFILL;
            end else phase_n = POLL_WAIT;

for (genvar lane = 0; lane < 4; lane++) begin : gen_lane
    localparam int Role = lane / 2;
    localparam int Channel = lane % 2; // read, write
    logic [1:0] port;
    logic [AxiIdWidth-1:0] id;
    logic enabled;
    assign port = Role == 0 ? victim_i : aggressor_i;
    assign id = AxiIdWidth'(port) << PrivateIdWidth;
    assign enabled = Role == 0 || has_a_i;
    assign event_chain[lane][0] = enabled && in_valid_i[Channel][port] && !in_hold_q[lane];
    assign event_chain[lane][1] = enabled && tr_valid_i[Channel] && tr_ready_i[Channel] && tr_id_i[Channel] == id;
    assign event_chain[lane][2] = enabled && out_valid_i[Channel] && !out_hold_q[Channel] && out_id_i[Channel] == id;
    assign event_chain[lane][3] = enabled && out_valid_i[Channel] && out_ready_i[Channel] && out_id_i[Channel] == id;
    assign event_chain[lane][4] = enabled && return_i[Channel] && return_id_i[Channel] == id;
    for (genvar stage = 0; stage < 4; stage++) begin : gen_stage
        dma_path_stage #(.TimeWidth(TimeWidth), .SumWidth(SumWidth), .CountWidth(CountWidth)) i_stage (
            .clk_i, .rst_ni, .clear_i(clear_i || arm_i), .run_i(run_q),
            .active_i, .open_i, .close_i, .time_i(time_q),
            .enter_i(event_chain[lane][stage]), .leave_i(event_chain[lane][stage+1]),
            .error_o(stage_error[lane*4+stage]), .data_o(result[lane][stage])
        );
    end

always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) in_hold_q[lane] <= 0;
    else if (clear_i || arm_i) in_hold_q[lane] <= 0;
    else if (run_q) in_hold_q[lane] <= enabled && in_valid_i[Channel][port] && !in_ready_i[Channel][port];
end

always_comb begin
    count_next = count_q;
    matched = leave_i && (count_q != 0 || enter_i);
    bad = (leave_i && !matched) || (enter_i && count_q == Depth && !leave_i);
    if (enter_i && !leave_i) count_next = count_q + 1'b1;
    if (leave_i && !enter_i) count_next = count_q - 1'b1;
    age = count_q == 0 ? '0 : time_i - stamps[head_q];
    whole = count_q == 0 ? active_i : born_in_window[head_q];
    sum_next = {1'b0, sum_q} + (SumWidth+1)'(age);
    area_next = {1'b0, area_q} + (SumWidth+1)'(count_q);
    data_o[0] = 64'(entered_q);
    data_o[1] = 64'(full_q);
    data_o[2] = 64'(carry_q);
    data_o[3] = 64'(sum_q);
    data_o[4] = 64'(max_q);
    data_o[5] = 64'(opening_q);
    data_o[6] = 64'(closing_q);
    data_o[7] = 64'(area_q);

end else if (run_i) begin
    if (bad) error_o <= 1;
    if (!bad) begin
        count_q <= count_next;
        if (enter_i) begin
            stamps[tail_q] <= time_i;
            born_in_window[tail_q] <= active_i;
            tail_q <= tail_q + 1'b1;
        end
        if (leave_i) head_q <= head_q + 1'b1;
        if (open_i) opening_q <= count_next;
        if (close_i) closing_q <= count_next;
        if (active_i) begin
            area_q <= area_next[SumWidth-1:0];
            if (area_next[SumWidth]) error_o <= 1;
            if (enter_i) begin
                entered_q <= entered_q + 1'b1;
                if (&entered_q) error_o <= 1;
            end
            if (matched) begin
                if (whole) begin
                    full_q <= full_q + 1'b1;
                    sum_q <= sum_next[SumWidth-1:0];
                    if (age > max_q) max_q <= age;
                    if (&full_q || sum_next[SumWidth]) error_o <= 1;
                end else begin
                    carry_q <= carry_q + 1'b1;
                    if (&carry_q) error_o <= 1;
                end
            end
        end

always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
        run_q <= 0; bad_q <= 0; time_q <= 0; out_hold_q <= 0;
        for (int ch = 0; ch < 2; ch++) out_held_id_q[ch] <= 0;
    end else if (clear_i || arm_i) begin
        run_q <= arm_i;
        bad_q <= arm_i && !idle_i;
        time_q <= 0;
        out_hold_q <= 0;
    end else if (run_q) begin
        time_q <= time_q + 1'b1;
        // The entire armed session must fit in 2^32 clocks (85.9s at 50MHz).
        if (&time_q) bad_q <= 1;
        if (close_i || abort_i) run_q <= 0;
        for (int lane = 0; lane < 4; lane++) begin
            if (in_hold_q[lane] && !in_valid_i[lane%2][lane < 2 ? victim_i : aggressor_i]) bad_q <= 1;
        end
        for (int ch = 0; ch < 2; ch++) begin
            if (out_hold_q[ch] && (!out_valid_i[ch] || out_id_i[ch] != out_held_id_q[ch])) bad_q <= 1;
            out_hold_q[ch] <= out_valid_i[ch] && !out_ready_i[ch];
            out_held_id_q[ch] <= out_id_i[ch];
            // This platform emits private ID=0; high bits identify the DMA.
            if ((tr_valid_i[ch] && |tr_id_i[ch][PrivateIdWidth-1:0]) ||
                (out_valid_i[ch] && |out_id_i[ch][PrivateIdWidth-1:0]) ||
                (return_i[ch] && |return_id_i[ch][PrivateIdWidth-1:0])) bad_q <= 1;
        end
    end

// PTW
logic ptw_init;
assign ptw_init = (state_q == PT) & ~iotlb_lu_hit;
logic ptw_error;
logic ptw_error_2S;

hpm_events_o                = '0;
hpm_events_o.filters.did    = req_data.did;
hpm_events_o.filters.pid_v  = req_data.pid_valid;
hpm_events_o.filters.pid    = req_data.pid;
hpm_events_o.filters.gscid  = gscid_q;
hpm_events_o.filters.pscid  = pscid_q;

// IOTLB lookup and PTW Walk
PT: begin

    msi_1S_data_n = msi_1S_content;

    // Signal PT Walk if occurred
    hpm_events_o.valid              = ~iotlb_lu_hit;
    hpm_events_o.etype_msk          = (rv_iommu::hpm_etype_mask_t'(1) << rv_iommu::IOTLB_MISS) |
                                      (rv_iommu::hpm_etype_mask_t'(en_1S_q) << rv_iommu::S1_PTW) |
                                      (rv_iommu::hpm_etype_mask_t'(en_2S_q) << rv_iommu::S2_PTW);
    hpm_events_o.filters.gscid_v    = 1'b1;
    hpm_events_o.filters.pscid_v    = 1'b1;

// Edge-triggered init control
logic edge_trigger_q, edge_trigger_n;
always_comb begin : ptw_init_control
    edge_trigger_n = edge_trigger_q;
    if (!edge_trigger_q && init_ptw_i)
        edge_trigger_n = 1'b1;
    if (edge_trigger_q && !init_ptw_i)
        edge_trigger_n = 1'b0;
end

// Check for possible misses to trigger PTW
IDLE: begin
    main_lvl_n          = LVL1;
    s1_lvl_n            = LVL1;
    global_mapping_n    = 1'b0;
    gpaddr_n            = '0;
    leaf_1Spte_n        = '0;
    pf_excep_n          = 1'b0;
    pt_data_corrupt_n   = 1'b0;

    if (init_ptw_i && !edge_trigger_q) begin

        state_n = MEM_ACCESS;
        iova_n = (imp_init_i) ? 
                 (addr_t'({pdt_gppn_i, 12'b0})) : 
                 (iova_i);
        implicit_trans_n = imp_init_i;

        unique case ({en_1S_i, en_2S_i})
